"""Worked timestamp-unit examples, with explicit units and UTC outputs."""

JAVASCRIPT = '''const seconds = 1700000000;
const milliseconds = 1700000000000;

console.log(new Date(seconds * 1000).toISOString());
// 2023-11-14T22:13:20.000Z
console.log(new Date(milliseconds).toISOString());
// 2023-11-14T22:13:20.000Z

// Passing seconds directly treats that number as milliseconds:
console.log(new Date(seconds).toISOString());
// 1970-01-20T16:13:20.000Z

console.log(new Date(1700000000123).toISOString());
// 2023-11-14T22:13:20.123Z'''

PYTHON = '''from datetime import datetime, timedelta, timezone

seconds = 1700000000
print(datetime.fromtimestamp(seconds, tz=timezone.utc).isoformat(timespec="milliseconds"))
# 2023-11-14T22:13:20.000+00:00

# Split integer milliseconds so the remainder is preserved, including before 1970.
for milliseconds in [1700000000123, -1]:
    whole_seconds, remainder_ms = divmod(milliseconds, 1000)
    instant = datetime.fromtimestamp(whole_seconds, tz=timezone.utc)
    instant += timedelta(milliseconds=remainder_ms)
    print(instant.isoformat(timespec="milliseconds"))
# 2023-11-14T22:13:20.123+00:00
# 1969-12-31T23:59:59.999+00:00'''

ZONE_JAVASCRIPT = '''const utc = Date.parse('2023-11-14T22:13:20Z');
const offset = Date.parse('2023-11-15T06:13:20+08:00');
console.log(utc === offset);
// true
console.log(utc);
// 1700000000000'''


def timestamp_units_guide(code_example, faq, copy):
    intro = '''<article class="guide-article"><header class="guide-header"><nav class="guide-breadcrumbs" aria-label="Breadcrumb"><a href="/">Home</a><span>/</span><a href="/guides/">Guides</a><span>/</span><span aria-current="page">Unix timestamp units</span></nav><span class="eyebrow">TIME & DATES · WORKED GUIDE</span><h1>Unix timestamps: seconds vs milliseconds</h1><p class="guide-deck">A numeric timestamp needs a unit. Interpreting seconds as milliseconds can move a modern date into 1970; interpreting milliseconds as seconds can send it far into the future. Start with the source’s contract, then check the conversion.</p><p class="guide-byline">By <a href="/about/">ParseCove</a> · Published <time datetime="2026-11-27">27 November 2026</time></p></header>
<nav class="guide-toc" aria-label="On this page"><strong>On this page</strong><a href="#timestamp-units">Check the unit</a><a href="#compare-epoch-units">Compare interpretations</a><a href="#timestamp-code">JavaScript & Python</a><a href="#timestamp-zone">UTC and time zones</a><a href="#timestamp-mistakes">Troubleshooting</a><a href="#timestamp-terms">Terms & FAQ</a></nav>
<section class="guide-section" id="timestamp-units"><h2>Seconds and milliseconds can describe the same instant</h2><p>The Unix epoch is <code>1970-01-01T00:00:00Z</code>. Unix timestamps conventionally use seconds; some APIs and libraries represent an epoch timestamp in milliseconds. Multiply seconds by 1,000 to obtain milliseconds. Dividing milliseconds by 1,000 can produce a fractional number of seconds.</p><div class="formula">milliseconds = seconds × 1,000</div><div class="table-wrap"><table><caption>One instant, with its unit included</caption><thead><tr><th>Representation</th><th>Value</th></tr></thead><tbody><tr><td>Seconds</td><td><code>1700000000</code></td></tr><tr><td>Milliseconds</td><td><code>1700000000000</code></td></tr><tr><td>ISO date in UTC</td><td><code>2023-11-14T22:13:20.000Z</code></td></tr></tbody></table></div><p>Modern dates often have 10 digits in seconds and 13 in milliseconds. That is a useful clue, not a unit definition. A millisecond timestamp close to the epoch can be very short, and a far-future timestamp in seconds can be long. Check the API schema, field documentation or producing code.</p><p class="guide-source">References: <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Date">MDN: Date and epoch milliseconds</a> · <a href="https://docs.python.org/3/library/datetime.html#datetime.datetime.fromtimestamp">Python: datetime.fromtimestamp</a>.</p></section>'''
    demo = '''<section class="epoch-unit-demo" id="compare-epoch-units" aria-labelledby="epoch-demo-heading"><div class="unit-demo-head"><div><span class="eyebrow">ONE NUMBER · TWO ASSUMPTIONS</span><h2 id="epoch-demo-heading">Compare seconds with milliseconds</h2></div><button class="button small" id="epoch-guide-reset">Reset example</button></div><p>Both outputs below use UTC. Neither column detects the intended unit: each shows what happens under one explicit assumption.</p><label for="epoch-guide-input">Integer timestamp</label><input id="epoch-guide-input" type="text" inputmode="numeric" class="mono" maxlength="24" value="1700000000" aria-describedby="epoch-guide-hint"><p class="hint" id="epoch-guide-hint">Enter an integer, including a minus sign for dates before the epoch. This comparison accepts up to 24 characters.</p><div class="quick-values"><span>Try:</span><button class="button small" data-epoch-example="seconds">10-digit example</button><button class="button small" data-epoch-example="milliseconds">13-digit example</button><button class="button small" data-epoch-example="early">Early milliseconds</button><button class="button small" data-epoch-example="negative">Before 1970</button><button class="button ghost" id="epoch-guide-clear">Clear</button></div><p class="error" id="epoch-guide-error" role="alert" hidden></p>
<div class="epoch-compare-grid"><section class="epoch-interpretation" aria-labelledby="epoch-seconds-heading"><h3 id="epoch-seconds-heading">Interpreted as seconds</h3><label class="sr-only" for="epoch-guide-seconds">UTC date if input is seconds</label><textarea id="epoch-guide-seconds" class="mono" rows="3" readonly placeholder="UTC date will appear here.">2023-11-14T22:13:20.000Z</textarea>'''+copy('epoch-guide-seconds','Copy UTC')+'''<p class="error" id="epoch-guide-seconds-error" role="alert" hidden></p><p class="hint">Input × 1,000 gives JavaScript epoch milliseconds.</p></section><section class="epoch-interpretation" aria-labelledby="epoch-ms-heading"><h3 id="epoch-ms-heading">Interpreted as milliseconds</h3><label class="sr-only" for="epoch-guide-milliseconds">UTC date if input is milliseconds</label><textarea id="epoch-guide-milliseconds" class="mono" rows="3" readonly placeholder="UTC date will appear here.">1970-01-20T16:13:20.000Z</textarea>'''+copy('epoch-guide-milliseconds','Copy UTC')+'''<p class="error" id="epoch-guide-milliseconds-error" role="alert" hidden></p><p class="hint">Input is already in JavaScript Date’s timestamp unit.</p></section></div><p class="hint">The comparison uses JavaScript Date’s supported range. A result can be outside that range for one unit and valid for the other. Four-digit years may expand to a signed, longer ISO year for distant dates.</p><noscript><p class="hint">JavaScript enables the comparison. The default worked outputs above remain readable without it.</p></noscript><div class="actions"><a class="button" href="/unix-timestamp-converter/?example=seconds">Open the seconds example</a><a class="button" href="/unix-timestamp-converter/?example=milliseconds">Open the milliseconds example</a></div></section>'''
    code = '''<section class="guide-section" id="timestamp-code"><h2>Convert timestamp units in JavaScript and Python</h2><p>The JavaScript Date constructor expects a numeric timestamp in milliseconds. Convert a known seconds value once before passing it in. <code>Date.now()</code> and <code>getTime()</code> already return milliseconds, so multiplying those values again is a unit mistake.</p><div id="epoch-js-example">'''+code_example('JavaScript: seconds, milliseconds and the 1970 mistake', JAVASCRIPT)+'''</div><p class="guide-source">Reference: <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Date/now">MDN: Date.now returns milliseconds</a>.</p><p>Python’s <code>datetime.fromtimestamp()</code> takes a timestamp in seconds. Pass an explicit timezone to obtain an aware UTC result. For integer milliseconds, the following example keeps the millisecond remainder instead of discarding it.</p><div id="epoch-python-example">'''+code_example('Python 3: UTC dates with the millisecond remainder preserved', PYTHON)+'''</div><p>Keep the original integer millisecond value if you need that precision. Converting it to whole seconds and dropping the remainder loses information. Python datetime and JavaScript Date also have different supported ranges; a date accepted by one is not automatically accepted by the other.</p></section>'''
    zone = '''<section class="guide-section" id="timestamp-zone"><h2>A time zone changes the displayed date, not the unit</h2><p><code>2023-11-14T22:13:20Z</code> and <code>2023-11-15T06:13:20+08:00</code> describe the same instant. Both map to <code>1700000000000</code> epoch milliseconds. A different calendar day in the display does not mean the timestamp has changed.</p><div id="epoch-zone-example">'''+code_example('JavaScript: two timezone-explicit dates, one timestamp', ZONE_JAVASCRIPT)+'''</div><p>When converting a date string in the <a href="/unix-timestamp-converter/">Unix timestamp converter</a>, include <code>Z</code> or an explicit numeric offset. A date and time without a timezone may be ambiguous. Named time zones can also have daylight-saving rules that depend on the date.</p></section>'''
    mistakes = '''<section class="guide-section" id="timestamp-mistakes"><h2>Check these causes before changing the number</h2><div class="table-wrap"><table><thead><tr><th>Symptom</th><th>What to check</th></tr></thead><tbody><tr><td>An expected modern date appears in 1970</td><td>Seconds may have been passed to an API expecting milliseconds. Confirm the source unit before multiplying.</td></tr><tr><td>A date lands far in the future or exceeds the range</td><td>Milliseconds may have been treated as seconds, or multiplied by 1,000 twice.</td></tr><tr><td>The date differs by several hours</td><td>Compare the displayed timezone and the original date string’s offset. A unit mismatch is a separate problem.</td></tr><tr><td>The last three digits disappear</td><td>Check whether a millisecond value was rounded or truncated to whole seconds.</td></tr><tr><td>An automatic unit choice looks wrong</td><td>Use the documented input unit explicitly. Digit counts and magnitude heuristics cannot establish the original meaning.</td></tr></tbody></table></div><p>For example, <code>999</code> milliseconds is <code>1970-01-01T00:00:00.999Z</code>. The same number in seconds is <code>1970-01-01T00:16:39.000Z</code>. Both are valid dates, so plausibility alone cannot identify the producer’s unit.</p></section>'''
    terms = '''<section class="guide-section" id="timestamp-terms"><h2>Terms used in this guide</h2><dl class="guide-terms"><div><dt>Unix epoch</dt><dd>The reference instant at the start of 1 January 1970 in UTC.</dd></div><div><dt>Epoch seconds</dt><dd>A numeric timestamp expressed in seconds relative to the epoch. The unit is part of its meaning.</dd></div><div><dt>Epoch milliseconds</dt><dd>The corresponding millisecond representation. One second equals 1,000 milliseconds.</dd></div><div><dt>UTC and Z</dt><dd>UTC is the time reference used by the examples. A trailing Z on an ISO date indicates a zero UTC offset.</dd></div></dl></section>'''
    questions = [
        ('Are all 13-digit values millisecond timestamps?', 'No. A digit count is only a clue for dates in a familiar range. The field could use a different unit, a far-future seconds value or an unrelated identifier. Confirm the source contract.'),
        ('Why does a timestamp show a different day in another timezone?', 'The same instant can fall on different local calendar days. Check an explicit UTC output before deciding that the timestamp or its unit is wrong.'),
        ('Can timestamps be negative?', 'Yes. Negative values represent instants before the epoch. -1 second and -1 millisecond are different instants, as the comparison shows.'),
        ('Does the tool accept fractional seconds, microseconds or nanoseconds?', 'The numeric modes accept integer seconds or integer milliseconds. The ISO date mode accepts up to three fractional second digits. Microsecond and nanosecond inputs need an explicit conversion and a decision about any precision loss; this tool does not guess those units.'),
    ]
    ending = '''<section class="guide-section guide-faq" id="timestamp-faq"><h2>Common questions</h2>'''+''.join(faq(*q) for q in questions)+'''</section><section class="guide-next"><span class="eyebrow">USE AN EXPLICIT UNIT</span><h2>Check a value in the Unix timestamp converter</h2><p>Select seconds or milliseconds when the source specifies its unit. The converter also supports timezone-explicit dates, batch conversion and a current-time display.</p><div class="actions"><a class="button primary" href="/unix-timestamp-converter/">Unix timestamp converter</a></div></section></article>'''
    return intro + demo + code + zone + mistakes + terms + ending
